(()=>{'use strict';let catalog=[];let selected='all';let search='';const names={salud:['Salud','Health'],profesional:['Profesional','Professional'],'real-estate':['Bienes raíces','Real estate'],negocios:['Negocios','Business'],finanzas:['Finanzas','Finance'],tecnologia:['Tecnología','Technology'],construccion:['Construcción','Construction'],marketing:['Marketing','Marketing'],idiomas:['Idiomas','Languages']};const categories=[['all','Todos','All'],...Object.entries(names).map(([k,v])=>[k,...v])];const icons={salud:'✚',profesional:'★','real-estate':'⌂',negocios:'▣',finanzas:'◈',tecnologia:'⌘',construccion:'⚒',marketing:'✦',idiomas:'◎'};const paArt={"construccion":"data:image/svg+xml;base64,","finanzas":"data:image/svg+xml;base64,","idiomas":"data:image/svg+xml;base64,","marketing":"data:image/svg+xml;base64,","negocios":"data:image/svg+xml;base64,","profesional":"data:image/svg+xml;base64,","real-estate":"data:image/svg+xml;base64,","salud":"data:image/svg+xml;base64,","tecnologia":"data:image/svg+xml;base64,"};const paPhotos={"profesional":"data:image/jpeg;base64,","tecnologia":"data:image/jpeg;base64,","construccion":"data:image/jpeg;base64,","negocios":"data:image/jpeg;base64,","marketing":"data:image/jpeg;base64,","idiomas":"data:image/jpeg;base64,","finanzas":"data:image/jpeg;base64,","real-estate":"data:image/jpeg;base64,","salud":"data:image/jpeg;base64,"};window.paFallbackArt=paArt;const lang=()=>window.plutonLanguage?.current()==='en'?'en':'es';const safe=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const b28CoursePhotos={"PA-101":"assets/b28-photo-01.jpg","RE-101":"assets/b28-photo-02.jpg","TE-101":"assets/b28-photo-03.jpg","MKT-201":"assets/b28-photo-04.jpg","FIN-201":"assets/b28-photo-05.jpg","ID-101":"assets/b28-photo-06.jpg","CO-101":"assets/b28-photo-07.jpg","PA-201":"assets/b28-photo-08.jpg","RE-102":"assets/b28-photo-09.jpg","PA-106":"assets/b28-photo-10.jpg","PA-105":"assets/b28-photo-11.jpg","HLT-201":"assets/b28-photo-12.jpg","PA-203":"assets/b28-photo-13.jpg","NE-101":"assets/foto-negocios.jpg","AI-101":"assets/b28-photo-15.jpg","BUS-201":"assets/b28-photo-16.jpg","RE-201":"assets/foto-real-estate.jpg","MA-101":"assets/b28-photo-18.jpg","FI-101":"assets/b28-photo-19.jpg","PA-102":"assets/foto-profesional.jpg"};function draw(){const root=document.getElementById('mainCatalog'),filters=document.getElementById('catalogFilters');if(!root||!filters)return;const en=lang()==='en';filters.innerHTML=categories.map(([id,es,enLabel])=>`<button type="button" class="${id===selected?'active':''}" data-catalog-filter="${id}">${safe(en?enLabel:es)}</button>`).join('');root.innerHTML=catalog.filter(c=>(selected==='all'||c.category===selected)&&(!search||[c.es,c.en,c.code,c.category].join(' ').toLocaleLowerCase().includes(search))).map(c=>`<article data-cat="${safe(c.category)}"><span class="code">${safe(c.code)}</span><div class="catalog-visual pa-illustrated" aria-hidden="true"><img src="${b28CoursePhotos[c.code]||paPhotos[c.category]||paPhotos.profesional}" onerror="console.warn('Course photo failed:',this.src);this.onerror=null;this.src=window.paFallbackArt?.[this.dataset.cat]||'assets/profesional.svg'" data-cat="${safe(c.category)}" alt="" loading="lazy" decoding="async" width="760" height="370"></div><h3>${safe(c[en?'en':'es'])}</h3><p>${safe((c.lessons||[]).length)} ${en?'introductory lessons':'lecciones introductorias'}</p><small>${safe((names[c.category]||[c.category,c.category])[en?1:0])}</small><a class="catalog-cta" href="courses.html?course=${encodeURIComponent(c.code)}">${en?'View lessons':'Ver lecciones'} →</a></article>`).join('');document.getElementById('catalogCount').textContent=(lang()==='en'?'Courses found: ':'Cursos encontrados: ')+catalog.filter(c=>(selected==='all'||c.category===selected)&&(!search||[c.es,c.en,c.code,c.category].join(' ').toLocaleLowerCase().includes(search))).length;filters.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.catalogFilter;draw()}))}document.addEventListener('DOMContentLoaded',()=>{document.getElementById('catalogSearch')?.addEventListener('input',e=>{search=e.target.value.trim().toLocaleLowerCase();draw()});fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Catalog');return r.json()}).then(data=>{catalog=data;draw()}).catch(()=>{const el=document.getElementById('mainCatalog');if(el)el.textContent=lang()==='en'?'Catalog temporarily unavailable.':'Catálogo temporalmente no disponible.'});document.getElementById('languageToggle')?.addEventListener('click',()=>setTimeout(draw,0));});})();